<?php
namespace App\Controllers\Customer;
use App\Core\Controller;use App\Helpers\CustomerAuth;use App\Services\Biteship;
class Checkout extends Controller {
 public function quote():void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$u=$this->customer();$address=$this->address((int)($this->getBody()['address_id']??0),(int)$u['id']);$cart=$this->cart((int)$u['id']);if(!$cart)$this->error('Cart is empty',422);try{$this->success(['address'=>$this->snapshot($address),'subtotal'=>$this->subtotal($cart),'rates'=>Biteship::quote($address,$this->items($cart))],'Shipping rates loaded');}catch(\Throwable $e){$this->error($e->getMessage(),422);}}
 public function create():void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$u=$this->customer();$b=$this->getBody();$address=$this->address((int)($b['address_id']??0),(int)$u['id']);$cart=$this->cart((int)$u['id']);if(!$cart)$this->error('Cart is empty',422);try{$rates=Biteship::quote($address,$this->items($cart));$match=null;foreach($rates as $r)if(($r['courier_company']??'')===($b['courier_company']??'')&&($r['courier_type']??'')===($b['courier_type']??'')){$match=$r;break;}if(!$match)$this->error('Selected shipping rate is no longer available',422);$now=$GLOBALS['now']??date('Y-m-d H:i:s');$sub=$this->subtotal($cart);$shipping=(float)($match['price']??0);$this->db()->beginTransaction();$id=(int)$this->db()->insert('vp_orders',['order_number'=>'VP'.date('Ymd').strtoupper(bin2hex(random_bytes(4))),'customer_id'=>(int)$u['id'],'address_id'=>(int)$address['id'],'status'=>'pending_payment','subtotal'=>$sub,'shipping_cost'=>$shipping,'total'=>$sub+$shipping,'recipient_snapshot'=>json_encode($this->snapshot($address)),'courier_company'=>$match['courier_company']??null,'courier_type'=>$match['courier_type']??null,'courier_service'=>$match['courier_service_name']??null,'created_at'=>$now,'updated_at'=>$now]);foreach($cart as $row){$this->db()->insert('vp_order_items',['order_id'=>$id,'configuration_id'=>(int)$row['configuration_id'],'product_name'=>$row['name'],'selections_snapshot'=>$row['selections_json'],'quantity'=>(int)$row['quantity'],'unit_price'=>$row['unit_price'],'total_price'=>(float)$row['unit_price']*(int)$row['quantity']]);$this->db()->update('vp_product_configurations',['status'=>'ordered','updated_at'=>$now],['id'=>(int)$row['configuration_id']]);}$this->db()->query('DELETE FROM vp_cart_items WHERE customer_id=?',[(int)$u['id']]);$this->db()->commit();$this->success(['id'=>$id,'orderNumber'=>$this->db()->query('SELECT order_number FROM vp_orders WHERE id=?',[$id])->row_array()['order_number'],'total'=>$sub+$shipping],'Order created');}catch(\Throwable $e){$this->db()->rollback();$this->error('Checkout failed',500);}}
 private function customer():array{$u=CustomerAuth::user();if(!$u)$this->error('Unauthorized',401);return $u;}private function address(int $id,int $c):array{$r=$this->db()->query('SELECT * FROM vp_customer_addresses WHERE id=? AND customer_id=? LIMIT 1',[$id,$c])->row_array();if(!$r)$this->error('Address not found',404);return $r;}private function cart(int $id):array{return $this->db()->query('SELECT ci.*,c.selections_json,p.name,p.weight_grams,p.length_mm,p.width_mm,p.height_mm FROM vp_cart_items ci INNER JOIN vp_product_configurations c ON c.id=ci.configuration_id INNER JOIN vp_products p ON p.id=c.product_id WHERE ci.customer_id=?',[$id])->result_array()?:[];}private function subtotal(array $c):float{return array_sum(array_map(fn($r)=>(float)$r['unit_price']*(int)$r['quantity'],$c));}private function items(array $c):array{return array_map(fn($r)=>['name'=>$r['name'],'description'=>'Vita Pictura order','value'=>(float)$r['unit_price']*(int)$r['quantity'],'length'=>(int)($r['length_mm']??0),'width'=>(int)($r['width_mm']??0),'height'=>(int)($r['height_mm']??0),'weight'=>(int)($r['weight_grams']??0),'quantity'=>(int)$r['quantity']],$c);}private function snapshot(array $a):array{return ['recipientName'=>$a['recipient_name'],'recipientPhone'=>$a['recipient_phone'],'addressLine'=>$a['address_line'],'areaId'=>$a['area_id'],'areaName'=>$a['area_name'],'postalCode'=>$a['postal_code'],'latitude'=>(float)$a['latitude'],'longitude'=>(float)$a['longitude']];}
}
